const { chromium } = require('playwright');
const path = require('path');
const outDir = path.join(process.cwd(), 'web/usability');

(async () => {
  const browser = await chromium.launch({
    headless: true,
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
  });

  // Fixture
  {
    const page = await browser.newPage({ viewport: { width: 1400, height: 1200 } });
    await page.goto('file://' + path.join(outDir, 'layers-tour.html'), { waitUntil: 'networkidle' });
    await page.screenshot({ path: path.join(outDir, 'layers-tour.png'), fullPage: true });
    await page.close();
    console.log('fixture ok');
  }

  async function loadTraceAndOpenLayersStep(page) {
    await page.addInitScript(() => {
      localStorage.setItem('simplify-viewer-tour-v1', '1');
      localStorage.removeItem('simplify-viewer-playback-tour-v1');
    });
    await page.goto('http://127.0.0.1:5050/?t=' + Date.now(), { waitUntil: 'domcontentloaded' });
    const skip = page.locator('#uiTourSkip');
    if (await skip.isVisible().catch(() => false)) await skip.click();

    // Choose preloaded trace 1
    const trigger = page.locator('#preloadedTrigger');
    if (await trigger.isVisible().catch(() => false)) {
      await trigger.click();
      const opt = page.locator('[data-value="1"]').first();
      if (await opt.isVisible().catch(() => false)) await opt.click();
      else await page.selectOption('#traceSelect', '1');
    } else {
      await page.selectOption('#traceSelect', '1');
    }
    await page.click('#loadBtn');
    await page.waitForFunction(() => document.body.classList.contains('playback-ready'), { timeout: 180000 });
    await page.waitForSelector('#uiTour:not([hidden])', { timeout: 30000 });

    // Advance to Layers step (index 3 of 5)
    for (let i = 0; i < 3; i++) {
      await page.click('#uiTourNext');
      await page.waitForTimeout(250);
    }
    await page.waitForFunction(() => {
      const t = document.getElementById('uiTourTitle');
      return t && t.textContent.trim() === 'Layers';
    }, { timeout: 10000 });
    await page.waitForTimeout(400);
  }

  // Desktop live
  {
    const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
    await loadTraceAndOpenLayersStep(page);
    const info = await page.evaluate(() => {
      const title = document.getElementById('uiTourTitle')?.textContent;
      const step = document.getElementById('uiTourStepLabel')?.textContent;
      const gloss = Array.from(document.querySelectorAll('#layersSection label'))
        .map((l) => l.textContent.replace(/\s+/g, ' ').trim())
        .filter((t) => /search circle|allowed area|anchor points|candidate region/.test(t));
      const reach = document.body.innerText.includes('reachability');
      const spotlight = !document.getElementById('uiTourSpotlight')?.hidden;
      const scrollW = document.documentElement.scrollWidth;
      return { title, step, gloss, reach, spotlight, scrollW };
    });
    console.log('desktop', info);
    await page.screenshot({ path: path.join(outDir, 'layers-tour-1280-live.png') });
    await page.close();
  }

  // Mobile live
  {
    const page = await browser.newPage({ viewport: { width: 390, height: 844 } });
